// Helper to extract German word from question text
function extractGermanWord(q: Question): string {
  const match = q.text.match(/má\s+(.+)\?/);
  return match ? match[1] : "";
}

// Helper to get article for a question
function getArticle(q: Question): string {
  return q.options[q.correct];
}

export interface FlashCard {
  german: string;
  czech: string;
  ko: string;
  pl?: string;
  en?: string;
  type: "noun" | "sentence";
  profession: Profession;
}

export function getAllFlashCards(): FlashCard[] {
  const nounCards: FlashCard[] = QUESTIONS.map((q) => ({
    german: `${getArticle(q)} ${extractGermanWord(q)}`,
    czech: q.translation,
    ko: q.translationKo,
    pl: q.translationPl,
    en: q.translationEn,
    type: "noun" as const,
    profession: q.profession,
  }));

  const sentenceCards: FlashCard[] = FILL_QUESTIONS.map((q) => ({
    german: q.sentence.replace("___", q.answer),
    czech: q.translation,
    ko: q.translationKo,
    pl: q.translationPl,
    en: q.translationEn,
    type: "sentence" as const,
    profession: q.profession,
  }));

  return [...nounCards, ...sentenceCards];
}

export function normalizeText(text: string): string {
  return text
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

/** Smart translation check: case-insensitive, trims whitespace, removes diacritics.
 * - Slash-separated variants: any single variant or keyword is accepted.
 * - Partial match: if input is part of the expected translation (≥4 chars), it's correct.
 * - Word-order flexibility: for multi-word terms without slashes, reversed word order is also accepted.
 */
export function isTranslationCorrect(input: string, expected: string): boolean {
  const normInput = normalizeText(input);
  const normExpected = normalizeText(expected);
  
  if (!normInput) return false;

  const variants = normExpected.split("/").map(v => v.trim()).filter(Boolean);
  
  for (const variant of variants) {
    if (normInput === variant) return true;
    
    // Partial match (Keyword matching)
    if (variant.includes(normInput) && normInput.length >= 4) {
      return true;
    }
    
    // Word order flexibility
    const inputWords = normInput.split(" ");
    const varWords = variant.split(" ");
    if (inputWords.length >= 2 && inputWords.length === varWords.length &&
        inputWords.slice().sort().join(" ") === varWords.slice().sort().join(" ")) {
      return true;
    }
    
    // Single keyword match
    if (varWords.some(w => w === normInput && w.length >= 3)) return true;
  }
  return false;
}

/** Filter questions by selected professions. Strict: only matching professions are returned. */
export function filterByProfession<T extends { profession: Profession }>(
  items: T[],
  selectedProfessions: Profession[]
): T[] {
  if (selectedProfessions.length === 0) return items;
  return items.filter(
    (item) => selectedProfessions.includes(item.profession)
  );
}
